import { test, expect } from '@playwright/test';

test.describe('Email Field Inline Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form>
        <div>
          <label for="email">Email</label>
          <input 
            id="email" 
            type="email" 
            placeholder="Enter your email"
            aria-describedby="email-error"
          />
          <span id="email-error" role="alert" style="color: red; display: none;"></span>
        </div>
      </form>
      <script>
        const emailInput = document.getElementById('email');
        const errorSpan = document.getElementById('email-error');

        emailInput.addEventListener('input', function() {
          const value = this.value;
          const isValid = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(value);

          if (value === '') {
            errorSpan.style.display = 'none';
            errorSpan.textContent = '';
          } else if (!isValid) {
            errorSpan.style.display = 'block';
            errorSpan.textContent = 'Please enter a valid email address';
          } else {
            errorSpan.style.display = 'none';
            errorSpan.textContent = '';
          }
        });
      </script>
    `);
  });

  test('should show validation error when typing invalid email', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const errorMessage = page.getByRole('alert');

    await emailInput.fill('invalid-email');

    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveText('Please enter a valid email address');
  });

  test('should hide validation error when typing valid email', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const errorMessage = page.getByRole('alert');

    await emailInput.fill('invalid');
    await expect(errorMessage).toBeVisible();

    await emailInput.fill('valid@example.com');
    await expect(errorMessage).not.toBeVisible();
  });

  test('should clear validation error when email field is emptied', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const errorMessage = page.getByRole('alert');

    await emailInput.fill('invalid-email');
    await expect(errorMessage).toBeVisible();

    await emailInput.clear();
    await expect(errorMessage).not.toBeVisible();
  });

  test('should validate email with multiple typing patterns', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const errorMessage = page.getByRole('alert');

    // Type invalid email character by character
    await emailInput.type('t');
    await expect(errorMessage).toBeVisible();

    await emailInput.type('e');
    await expect(errorMessage).toBeVisible();

    await emailInput.type('st@');
    await expect(errorMessage).toBeVisible();

    await emailInput.type('example.com');
    await expect(errorMessage).not.toBeVisible();
  });
});
